const MAILBOX = String((typeof $env !== 'undefined' && $env.SENDER_EMAIL) || 'you@example.com');
const DEF = () => ({
  rev: 0, updated: null,
  notes: { global: [], leads: {} },
  campaigns: [
    { id: 'c-gulf1', name: 'Gulf agencies - white-label', status: 'active', account: MAILBOX, region: 'Gulf (KSA, UAE, Qatar, Oman, Kuwait, Bahrain)', color: '#f97316', created: new Date().toISOString().slice(0, 10), desc: 'Sun-Thu office hours, white-label web/UI/SaaS pitch.' },
    { id: 'c-core', name: 'Core agencies', status: 'active', account: MAILBOX, region: 'US / UK / EU / India', color: '#38bdf8', created: new Date().toISOString().slice(0, 10), desc: 'Default campaign for everything that is not assigned elsewhere.' }
  ],
  assign: {}, uploads: [], held: {}, stage: {},
  accounts: [{ email: MAILBOX, label: 'Primary mailbox', provider: 'SMTP', daily_limit: Number((typeof $env !== 'undefined' && $env.DAILY_LIMIT) || 5) }],
  settings: { goal_mrr: 5000, goal_price: 1500, copy_drafts: {} }
});

const j = $('Get - Extract Doc').first()?.json || {};
const raw = j.doc || j.data || {};
const doc = Object.assign(DEF(), (raw && typeof raw === 'object' && !Array.isArray(raw)) ? raw : {});
const rj = $('Get - Extract Replies').first()?.json || {};
let replies = rj.doc || rj.data || [];
if (!Array.isArray(replies)) replies = Array.isArray(replies.replies) ? replies.replies : [];
return [{ json: { ok: true, doc, replies, now: new Date().toISOString() } }];

const MAILBOX = String((typeof $env !== 'undefined' && $env.SENDER_EMAIL) || 'you@example.com');
const DEF = () => ({
  rev: 0, updated: null,
  notes: { global: [], leads: {} },
  campaigns: [
    { id: 'c-gulf1', name: 'Gulf agencies - white-label', status: 'active', account: MAILBOX, region: 'Gulf (KSA, UAE, Qatar, Oman, Kuwait, Bahrain)', color: '#f97316', created: new Date().toISOString().slice(0, 10), desc: 'Sun-Thu office hours, white-label web/UI/SaaS pitch.' },
    { id: 'c-core', name: 'Core agencies', status: 'active', account: MAILBOX, region: 'US / UK / EU / India', color: '#38bdf8', created: new Date().toISOString().slice(0, 10), desc: 'Default campaign for everything that is not assigned elsewhere.' }
  ],
  assign: {}, uploads: [], held: {}, stage: {},
  accounts: [{ email: MAILBOX, label: 'Primary mailbox', provider: 'SMTP', daily_limit: Number((typeof $env !== 'undefined' && $env.DAILY_LIMIT) || 5) }],
  settings: { goal_mrr: 5000, goal_price: 1500, copy_drafts: {} }
});

const j = $('Op - Extract Doc').first()?.json || {};
const raw = j.doc || j.data || {};
const doc = Object.assign(DEF(), (raw && typeof raw === 'object' && !Array.isArray(raw)) ? raw : {});
const b = $('Op - Webhook').first().json.body || {};
const em = (s) => String(s || '').trim().toLowerCase();
const nid = () => Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
const now = new Date().toISOString();
const fail = (m) => [{ json: { str: null, result: { ok: false, error: m } } }];
const op = b.op;
if (op === 'note.add') {
  const text = String(b.text || '').trim().slice(0, 4000); if (!text) return fail('empty note');
  const n = { id: nid(), ts: now, text, pinned: false };
  if (b.scope === 'lead') { const k = em(b.key); if (!k) return fail('no lead'); (doc.notes.leads[k] = doc.notes.leads[k] || []).unshift(n); }
  else doc.notes.global.unshift(n);
} else if (op === 'note.del' || op === 'note.pin' || op === 'note.edit') {
  const list = b.scope === 'lead' ? (doc.notes.leads[em(b.key)] || []) : doc.notes.global;
  const i = list.findIndex(x => x.id === b.id); if (i < 0) return fail('note not found');
  if (op === 'note.del') list.splice(i, 1);
  else if (op === 'note.pin') list[i].pinned = !list[i].pinned;
  else { list[i].text = String(b.text || '').slice(0, 4000); list[i].edited = now; }
  if (b.scope === 'lead' && !list.length) delete doc.notes.leads[em(b.key)];
} else if (op === 'campaign.save') {
  const c = b.campaign || {}; if (!String(c.name || '').trim()) return fail('campaign needs a name');
  const id = c.id || ('c-' + nid());
  const rec = { id, name: String(c.name).slice(0, 80), status: ['active', 'paused', 'draft'].includes(c.status) ? c.status : 'draft', account: String(c.account || ''), region: String(c.region || '').slice(0, 120), color: String(c.color || '#a78bfa').slice(0, 9), desc: String(c.desc || '').slice(0, 400), created: c.created || now.slice(0, 10) };
  const i = doc.campaigns.findIndex(x => x.id === id); if (i >= 0) doc.campaigns[i] = Object.assign(doc.campaigns[i], rec); else doc.campaigns.push(rec);
} else if (op === 'campaign.del') {
  doc.campaigns = doc.campaigns.filter(x => x.id !== b.id);
  for (const k of Object.keys(doc.assign)) if (doc.assign[k] === b.id) delete doc.assign[k];
  delete doc.held[b.id];
} else if (op === 'assign') {
  const list = Array.isArray(b.emails) ? b.emails.map(em).filter(Boolean) : [];
  if (b.campaign && !doc.campaigns.some(x => x.id === b.campaign)) return fail('unknown campaign');
  for (const e of list) { if (b.campaign) doc.assign[e] = b.campaign; else delete doc.assign[e]; }
} else if (op === 'held.set') {
  if (!b.campaign) return fail('no campaign');
  if (Array.isArray(b.ids) && b.ids.length) doc.held[b.campaign] = b.ids.map(String); else delete doc.held[b.campaign];
} else if (op === 'upload.log') {
  doc.uploads.unshift(Object.assign({ ts: now }, b.entry || {})); doc.uploads = doc.uploads.slice(0, 100);
} else if (op === 'settings.set') {
  const s = b.settings || {};
  if (s.goal_mrr !== undefined) doc.settings.goal_mrr = Number(s.goal_mrr) || 0;
  if (s.goal_price !== undefined) doc.settings.goal_price = Number(s.goal_price) || 0;
  if (s.copy_drafts && typeof s.copy_drafts === 'object') { doc.settings.copy_drafts = doc.settings.copy_drafts || {}; for (const k of Object.keys(s.copy_drafts)) { if (s.copy_drafts[k] === null) delete doc.settings.copy_drafts[k]; else doc.settings.copy_drafts[k] = { subject: String(s.copy_drafts[k].subject || '').slice(0, 300), body: String(s.copy_drafts[k].body || '').slice(0, 8000) }; } }
} else if (op === 'stage.set') {
  const k = em(b.key); if (!k) return fail('no lead'); doc.stage = doc.stage || {};
  if (b.value) doc.stage[k] = String(b.value).slice(0, 20); else delete doc.stage[k];
} else if (op === 'account.save') {
  const a = b.account || {}; if (!/^[^@\s]+@[^@\s]+$/.test(a.email || '')) return fail('bad email');
  const i = doc.accounts.findIndex(x => x.email === a.email); const rec = { email: a.email, label: String(a.label || '').slice(0, 60), provider: String(a.provider || '').slice(0, 40), daily_limit: Number(a.daily_limit) || 0, inactive: !!a.inactive };
  if (i >= 0) doc.accounts[i] = Object.assign(doc.accounts[i], rec); else doc.accounts.push(rec);
} else return fail('unknown op ' + op);
doc.rev = (doc.rev || 0) + 1; doc.updated = now;
return [{ json: { str: JSON.stringify(doc), result: { ok: true, rev: doc.rev, doc } } }];
